"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[65709],{56750:e=>{e.exports=JSON.parse('{"functions":[{"name":"start","desc":"Runs one shell-turret weapon\'s client: `Config` is its config module\\n(BurstCannonConfig field set), `packets` its own packets.","params":[{"name":"Config","desc":"","lua_type":"any"},{"name":"packets","desc":"","lua_type":"ShellPackets"}],"returns":[],"function_type":"static","source":{"line":81,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/ShellWeapon.luau"}}],"properties":[],"types":[{"name":"ShellPackets","desc":"The weapon\'s own packets (same shapes as the BurstCannon ones). Heat mode has\\nno `Reload`; no-splash shots send `Impact` (hit position).","lua_type":"{ Mount: any, Trigger: any, Aim: any, Reload: any?, Fired: any, Impact: any? }","source":{"line":61,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/ShellWeapon.luau"}}],"name":"ShellWeapon","desc":"The client side of the shell-firing train turrets (Burst Cannon, AutoCannon).\\n`start(Config, packets)` renders every placed turret of one weapon for all\\nplayers: one `TurretRig` per turret in `workspace.PlacedObjects` (`Discovery`\\nfollows the PlaceableName attribute and drops the rig when the turret is\\nremoved or stashed), eased toward the replicated `AimYaw` / `AimPitch`, and\\nthe weapon\'s `Fired` shots: barrel fold (a per-turret `Recoil` written after\\nthe rig updates), muzzle flash, a pooled neon tracer in `Config.TracerColor`\\nand the fire sound. Impact sound comes from `ExplosionAt` (`Config.WeaponName`);\\nthe reload sound plays once when `Reloading` turns true. Shots whose shooter\\nis the local player while the local player mans that turret are skipped: the\\n`Gunner` hooks below predict them. The tracers are client-only Parts. `Gunner`\\nalso gets each turret\'s mount prompt and its step runs first in the per-frame\\norder. Every `start` call keeps its own state, pool and render step.\\n\\n**Heat mode** (Energy Cannon: `Config.HeatPerShot` is set): the gunner predicts\\nheat with `EnergyCannonMath` instead of ammo (resynced from the `Heat` /\\n`Overheated` attributes on mount and on every overheat edge), there is no R\\nreload, every client plays the overheat / vent sounds on the `Overheated`\\nedges, and `HeatGlow` recolours the model\'s glow parts. With `packets.Impact`\\n(no-splash bolts) each hit gets a flash and `Config.HitSound`.","realm":["Client"],"source":{"line":27,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/ShellWeapon.luau"}}')}}]);